+// file (their probe rides WORKFLOW_FILE: ai-teammate.yml); see the
+// FOLLOW-UP note in the header.
 var DEFAULT_WORKFLOW_FILE = 'ai-teammate.yml';

 // Active-state vocabulary — branchLegGuard parity, one list.
diff --git a/js/unit-tests/run_aiTeammateTemplate.json b/js/unit-tests/run_aiTeammateTemplate.json
new file mode 100644
index 00000000..90600a66
--- /dev/null
+++ b/js/unit-tests/run_aiTeammateTemplate.json
@@ -0,0 +1,11 @@
+{
+  "name": "JSRunner",
+  "params": {
+    "jsPath": "js/unit-tests/testRunner.js",
+    "jobParams": {
+      "testFiles": [
+        "js/unit-tests/test_aiTeammateTemplate.js"
