function extractJobIf(yml) {
    var blocks = foldedIfBlocks(yml);
    for (var k = 0; k < blocks.length; k++) {
        if (blocks[k].indexOf('needs.dedup.outputs.proceed') !== -1) return blocks[k];
    }
    return blocks.length ? blocks[0] : '';
}

