            if (/^\s*$/.test(lines[j])) continue;
            if (!/^ {5,}/.test(lines[j])) break;
            parts.push(lines[j].replace(/^\s+/, ''));
        }
        blocks.push(parts.join(' '));
    }
    return blocks;
